/** Adds derived fields so the rest of the app never recalculates them. */
function decorate(raw) {
  const discount = raw.originalPrice
    ? Math.round((1 - raw.price / raw.originalPrice) * 100)
    : 0;

  return {
    ...raw,
    discount,
    isSale: discount > 0,
    images: galleryFor(raw.photo, raw.altPhoto),
    /** Lower-cased haystack used by the search overlay. */
    searchIndex: [raw.name, raw.category, raw.gender, raw.description, ...(raw.highlights || [])]
      .join(' ')
      .toLowerCase(),
  };
}

export const products = RAW.map(decorate);

export const getProductById = (id) => products.find((p) => p.id === id);

export const CATEGORIES = [...new Set(products.map((p) => p.category))].sort();

export const GENDERS = ['Women', 'Men', 'Unisex'];

export const SIZE_GROUPS = [
  { label: 'Clothing', sizes: LETTER_SIZES },
  { label: 'Waist', sizes: WAIST_SIZES },
  { label: 'Footwear', sizes: SHOE_SIZES },
];

export const PRICE_BOUNDS = {
  min: 0,
  max: Math.ceil(Math.max(...products.map((p) => p.price)) / 500) * 500,
};

export const SORT_OPTIONS = [
  { value: 'featured', label: 'Featured' },
  { value: 'new', label: 'Newest first' },
  { value: 'price-asc', label: 'Price: low to high' },
  { value: 'price-desc', label: 'Price: high to low' },
  { value: 'rating', label: 'Top rated' },
  { value: 'discount', label: 'Biggest discount' },
];

export const newArrivals = products.filter((p) => p.isNew);
export const bestSellers = products.filter((p) => p.isBestSeller);
export const onSale = products
  .filter((p) => p.isSale)
  .sort((a, b) => b.discount - a.discount);

/** Products from the same category, excluding the current one. */
export function relatedProducts(product, limit = 4) {
  if (!product) return [];
  const sameCategory = products.filter(
    (p) => p.id !== product.id && p.category === product.category
  );
  const sameGender = products.filter(
    (p) => p.id !== product.id && p.gender === product.gender && p.category !== product.category
  );
  return [...sameCategory, ...sameGender].slice(0, limit);
}

export default products;
